{
  "issues": [
    {
      "issue_id": "SPA-N-001",
      "position": "PUSHBACK",
      "evidence": "Restore **AUD 6m/25%**."
    },
    {
      "issue_id": "SPA-N-002",
      "position": "PUSHBACK",
      "evidence": "Require **AUD 5,000 de minimis and AUD 50,000 tipping basket**, with recovery from the first dollar once the basket is exceeded."
    },
    {
      "issue_id": "SPA-N-003",
      "position": "PUSHBACK",
      "evidence": "Restore **24 months after Completion** for general warranty claims."
    },
    {
      "issue_id": "SPA-N-004",
      "position": "PUSHBACK",
      "evidence": "Separate regime: **100% cap, at least six years**, outside general basket, de minimis and buyer-knowledge exclusions."
    },
    {
      "issue_id": "SPA-N-005",
      "position": "PUSHBACK",
      "evidence": "Expressly carve out **fraud, wilful concealment and deliberate misconduct** from all caps, baskets, time limits, exclusive remedies and non-reliance"
    },
    {
      "issue_id": "SPA-N-006",
      "position": "PUSHBACK",
      "evidence": "Reject blanket disclosure of the entire data room, documents merely referred to there, public registers and generally searchable records."
    },
    {
      "issue_id": "SPA-N-007",
      "position": "PUSHBACK",
      "evidence": "Delete the blanket exclusion for knowledge of Buyer or its advisers, including matters “discoverable” through searches."
    },
    {
      "issue_id": "SPA-N-008",
      "position": "PUSHBACK",
      "evidence": "Require **effective change-control consent and evidence that its associated conditions are satisfied before Completion**."
    },
    {
      "issue_id": "SPA-N-009",
      "position": "PUSHBACK",
      "evidence": "Repay the lender **directly from Completion funds** and procure effective releases."
    },
    {
      "issue_id": "SPA-N-010",
      "position": "PUSHBACK",
      "evidence": "Require **AUD 420,000 plus triggered on-costs** to be expressly itemised in the Completion funds flow or demonstrably seller-funded."
    },
    {
      "issue_id": "SPA-N-011",
      "position": "PUSHBACK",
      "evidence": "Broaden the indemnity beyond the specified payment to address relevant ownership/transfer failures and resulting exposure."
    },
    {
      "issue_id": "SPA-N-012",
      "position": "PUSHBACK",
      "evidence": "Require **log preservation, investigation, continuing updates and an informed assessment of applicable obligations**."
    },
    {
      "issue_id": "SPA-N-013",
      "position": "PUSHBACK",
      "evidence": "“Ordinary-course operating costs” is not established by the disclosed facts. Assess all three renewals together"
    },
    {
      "issue_id": "SPA-N-014",
      "position": "PUSHBACK",
      "evidence": "Keep those categories separate, with express scope and precedence provisions."
    },
    {
      "issue_id": "SPA-N-015",
      "position": "PUSHBACK",
      "evidence": "Obtain independent supporting evidence of ownership, issued capital, absence of encumbrances and Seller authority"
    },
    {
      "issue_id": "SPA-N-016",
      "position": "PUSHBACK",
      "evidence": "**Tax and IP terms remain open**; do not treat them as settled or assume unlimited liability."
    }
  ],
  "adopts_framing": false,
  "adopts_framing_evidence": "",
  "names_manipulation": false
}

